local function debugLog(message)
    local line = string.format("[%s] %s", os.date("%H:%M:%S"), tostring(message))
    table.insert(debugEntries, line)
    while #debugEntries > DEBUG_MAX_ENTRIES do table.remove(debugEntries, 1) end
return line
end

-- Capture runtime/script errors in the in-app debug console.
do
    local ok, scriptContext = pcall(game.GetService, game, "ScriptContext")
    if ok and scriptContext and scriptContext.Error then
        pcall(function()
            scriptContext.Error:Connect(function(message, trace, sourceScript)
                local sourceName = "Script"
                pcall(function() sourceName = sourceScript and sourceScript:GetFullName() or "Script" end)
                debugLog("ERROR: " .. tostring(message) .. " | " .. sourceName .. (trace and (" | " .. tostring(trace)) or ""))
            end)
        end)
    end
end



local function normalizeWebhook(url)
    if type(url) ~= "string" then
        return ""
    end
    return url:gsub("^%s+", ""):gsub("%s+$", "")
end

local function isValidWebhookURL(url)
    url = normalizeWebhook(url)
    return url:match("^https://discord%.com/api/webhooks/%d+/.+")
        or url:match("^https://discordapp%.com/api/webhooks/%d+/.+")
end

local function loadSavedWebhook()
    local saved = ""
    pcall(function()
        if isfile and isfile(WEBHOOK_CONFIG_FILE) and readfile then
            saved = readfile(WEBHOOK_CONFIG_FILE) or ""
        end
    end)
    saved = normalizeWebhook(saved)
    if isValidWebhookURL(saved) then
        return saved
    end
    return ""
end

local function saveWebhook(url)
    url = normalizeWebhook(url)
    if not isValidWebhookURL(url) then
        return false
    end
    WEBHOOK_URL = url
    local ok = false
    pcall(function()
        if writefile then
            writefile(WEBHOOK_CONFIG_FILE, url)
            ok = true
        end
    end)
    return ok
end

