-- User-provided webhook logo. The UI references the supplied local asset; no
-- image is generated or modified by the script. Executors that support
-- getcustomasset/getsynasset can resolve the file directly.
local WEBHOOK_LOGO_FILE = "A-H-HUB-Logo.png"
local function resolveWebhookLogo()
    local loaders = {
        function(path) return getcustomasset and getcustomasset(path) end,
        function(path) return getsynasset and getsynasset(path) end,
    }
    for _, loader in ipairs(loaders) do
        local ok, asset = pcall(loader, WEBHOOK_LOGO_FILE)
        if ok and type(asset) == "string" and asset ~= "" then
            return asset
        end
    end
    return ""
end
local WEBHOOK_LOGO_ASSET = ""
local WEBHOOK_LOGO_BASE64 = [[]]

local function decodeBase64(data)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local lookup = {}
    for i = 1, #alphabet do lookup[alphabet:sub(i, i)] = i - 1 end
    data = tostring(data):gsub("[^%w%+%/%=]", "")
    local out = {}
    local buffer, bits = 0, 0
    for i = 1, #data do
        local ch = data:sub(i, i)
        if ch == "=" then break end
        local value = lookup[ch]
        if value then
            buffer = buffer * 64 + value
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                local byte = math.floor(buffer / (2 ^ bits)) % 256
                out[#out + 1] = string.char(byte)
                buffer = buffer % (2 ^ bits)
            end
        end
    end
    return table.concat(out)
end

local EMBEDDED_WEBHOOK_LOGO_BYTES
local local_dummy = nil
pcall(function() EMBEDDED_WEBHOOK_LOGO_BYTES = decodeBase64(WEBHOOK_LOGO_BASE64) end)

