local function getRequestFunction()
    return request
        or http_request
        or (syn and syn.request)
        or (http and http.request)
end

local function readNumericGuiObject(obj)
    if not obj then return nil end
    local text = nil
    pcall(function()
        if obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
            text = obj.Text
        elseif obj:IsA("IntValue") or obj:IsA("NumberValue") then
            text = obj.Value
        end
    end)
    if text == nil then return nil end
    local cleaned = tostring(text):gsub(",", ""):gsub("%s+", "")
    return tonumber(cleaned:match("%-?%d+%.?%d*"))
end

local function findPath(root, path)
    local current = root
    for part in string.gmatch(path, "[^%.]+") do
        if not current then return nil end
        current = current:FindFirstChild(part)
    end
    return current
end

local function getBalance()
    local ok, result = pcall(function()
        local playerGui = player and player:FindFirstChild("PlayerGui")
        if not playerGui then return nil end

        -- These paths were found in the GUI dump and point specifically at
        -- the Coins amount, rather than arbitrary numeric labels.
        local paths = {
            "CrossPlatform.Shop.Medium.Title.Coins.Container.Amount",
            "CrossPlatform.Shop.Small.Container.Title.Container.Coins.Container.Amount",
            "CrossPlatform.Shop.Large.BottomBar.Coins.Amount",
        }

        for _, path in ipairs(paths) do
            local value = readNumericGuiObject(findPath(playerGui, path))
            if value ~= nil then
                return value
            end
        end

        -- Fallback: only inspect objects named Amount underneath a Coins
        -- container. This avoids timers, prices, XP, levels, and event counters.
        for _, obj in ipairs(playerGui:GetDescendants()) do
            if obj.Name == "Amount" and obj.Parent then
                local parentName = string.lower(obj.Parent.Name)
                local grandParent = obj.Parent.Parent
                local grandName = grandParent and string.lower(grandParent.Name) or ""
                if parentName == "coins" or grandName == "coins" then
                    local value = readNumericGuiObject(obj)
                    if value ~= nil then
                        return value
                    end
                end
            end
        end

        return nil
    end)

    if not ok then
        warn("⚠️ getBalance failed:", tostring(result))
        return nil
    end
    return result
end

local function buildMultipartBody(payloadJson, fileName, fileBytes, mimeType)
    if type(payloadJson) ~= "string" or type(fileName) ~= "string" or type(fileBytes) ~= "string" then
        return nil, nil
    end
    mimeType = mimeType or "application/octet-stream"
    local boundary = "----AHHubBoundary" .. tostring(math.random(100000, 999999)) .. tostring(os.clock()):gsub("%D", "")
    local body = table.concat({
        "--" .. boundary .. "\r\n",
        'Content-Disposition: form-data; name="payload_json"\r\n',
        "Content-Type: application/json; charset=utf-8\r\n\r\n",
        payloadJson, "\r\n",
        "--" .. boundary .. "\r\n",
        'Content-Disposition: form-data; name="files[0]"; filename="' .. fileName .. '"\r\n',
        "Content-Type: " .. mimeType .. "\r\n",
        "Content-Transfer-Encoding: binary\r\n\r\n",
        fileBytes, "\r\n",
        "--" .. boundary .. "--\r\n"
    })
    return body, "multipart/form-data; boundary=" .. boundary
end

local function readWebhookLogoBytes()
    -- The supplied logo is embedded byte-for-byte so the webhook does not
    -- depend on the executor having the ChatGPT-uploaded filename locally.
    if type(EMBEDDED_WEBHOOK_LOGO_BYTES) == "string" and #EMBEDDED_WEBHOOK_LOGO_BYTES > 0 then
        return EMBEDDED_WEBHOOK_LOGO_BYTES
    end
    if not readfile then return nil end
    local candidates = {
        WEBHOOK_LOGO_FILE,
        "A-H-HUB-Logo.png",
        "assets/" .. WEBHOOK_LOGO_FILE,
        "assets/A-H-HUB-Logo.png"
    }
    for _, path in ipairs(candidates) do
        local ok, bytes = pcall(readfile, path)
        if ok and type(bytes) == "string" and #bytes > 0 then
            return bytes
        end
    end
    return nil
end

local function postWebhookPayload(payload)
    local req = getRequestFunction()
    if type(req) ~= "function" then
        warn("❌ No HTTP request function available.")
        return false, "request-unavailable"
    end

    local logoBytes = readWebhookLogoBytes()
    local payloadJson
    local requestBody
    local contentType

    if logoBytes then
        payload.attachments = payload.attachments or {}
        payload.attachments[1] = {
            id = 0,
            filename = "A-H-HUB-Logo.png",
            description = "A&H HUB custom logo"
        }
        payload.embeds = payload.embeds or {}
        if payload.embeds[1] then
            -- Use the uploaded attachment as the embed thumbnail, not a large body image.
            -- Discord resolves attachment:// URLs against the multipart file
            -- registered above, so the actual webhook uses the supplied logo.
            payload.embeds[1].thumbnail = { url = "attachment://A-H-HUB-Logo.png" }
            payload.embeds[1].image = nil
        end
        payloadJson = HttpService:JSONEncode(payload)
        requestBody, contentType = buildMultipartBody(payloadJson, "A-H-HUB-Logo.png", logoBytes, "image/png")
    else
        payloadJson = HttpService:JSONEncode(payload)
        requestBody = payloadJson
        contentType = "application/json"
        warn("⚠️ Custom webhook image was not found at the configured local asset path: " .. tostring(WEBHOOK_LOGO_FILE))
    end

    if not requestBody then
        return false, "payload-build-failed"
    end

    local success, response = pcall(function()
        return req({
            Url = WEBHOOK_URL .. "?wait=true",
            Method = "POST",
            Headers = { ["Content-Type"] = contentType },
            Body = requestBody
        })
    end)

    if not success then
        warn("❌ Webhook request error:", tostring(response))
        return false, "request-error"
    end

    local statusCode = response and tonumber(response.StatusCode or response.Status or response.status or response.status_code)
    if statusCode and statusCode >= 200 and statusCode < 300 then
        return true, logoBytes and "delivered" or "delivered-no-image"
    end

    warn("❌ Discord rejected webhook. HTTP:", tostring(statusCode or "unknown"))
    if response and response.Body then warn("Discord response:", tostring(response.Body)) end
    return false, "http-error"
end

local function webhookMark(success, detail)
    if success then
        webhookLastSuccess = os.date("%H:%M:%S")
        webhookLastError = "None"
        debugLog("Webhook -> Success (" .. tostring(detail or "ok") .. ")")
    else
        webhookLastError = tostring(detail or "unknown error")
        debugLog("Webhook -> Error: " .. webhookLastError)
    end
    if webhookSuccessLabel and webhookSuccessLabel.Parent then webhookSuccessLabel.Text = "Last success: " .. webhookLastSuccess end
    if webhookErrorLabel and webhookErrorLabel.Parent then webhookErrorLabel.Text = "Last error: " .. webhookLastError end
end

sendWebhookEvent = function(eventName, extra)
    if not webhookEnabled or not isValidWebhookURL(WEBHOOK_URL) then return false end
    local fields = {}
    extra = extra or {}
    if webhookIncludeAccount then
        table.insert(fields, {name="Account", value=string.format("**Username:** `%s`\n**Display:** `%s`", tostring(player.Name), tostring(player.DisplayName)), inline=true})
    end
    if webhookIncludeRound then table.insert(fields, {name="Round", value="`" .. tostring(roundNumber or 0) .. "`", inline=true}) end
    if webhookIncludeBalance then table.insert(fields, {name="Balance", value="🪙 `" .. tostring(extra.balance or getBalance() or "Unknown") .. "`", inline=true}) end
    if webhookIncludeRole then table.insert(fields, {name="Role", value="`" .. tostring(currentRole or "Unknown") .. "`", inline=true}) end
    if webhookIncludeState then table.insert(fields, {name="State", value="`" .. tostring(roundState or "WAITING") .. "`", inline=true}) end
    local payload = {username="A&H HUB", embeds={{title="💎 A&H HUB • " .. tostring(eventName), description="Premium status event • **" .. tostring(player.DisplayName) .. "**", color=16766720, fields=fields, footer={text="A&H HUB • Premium Auto-Farm"}, timestamp=DateTime.now():ToIsoDate()}}}
    local ok, mode = postWebhookPayload(payload)
    webhookMark(ok, ok and mode or "delivery failed")
    return ok
end

local function sendBalance(round, balance)
    if not webhookEnabled then return false end
    if normalizeWebhook(WEBHOOK_URL) == "" then return false end
    local req = getRequestFunction()
    if type(req) ~= "function" then
        warn("❌ No HTTP request function available.")
        return false
    end

    local elapsed = math.max(0, os.time() - injectedAt)
    local uptime = string.format(
        "%02d:%02d:%02d",
        math.floor(elapsed / 3600),
        math.floor((elapsed % 3600) / 60),
        elapsed % 60
    )

    local data = {
        username = "botfarm",
        embeds = {{
            title = "💎 A&H HUB  •  COIN REPORT",
            description = "Premium farm report • **" .. tostring(player.DisplayName) .. "**",
            color = 16766720,
            fields = {
                {
                    name = "👤 Account",
                    value = string.format(
                        "**Username:** \`%s\`\n**Display:** \`%s\`",
                        tostring(player.Name),
                        tostring(player.DisplayName)
                    ),
                    inline = true
                },
                {
                    name = "📊 Progress",
                    value = string.format(
                        "**Round:** \`%d\`\n**Balance:** 🪙 \`%s\`\n**Role:** \`%s\`",
                        tonumber(round) or 0,
                        balance ~= nil and tostring(balance) or "Unknown",
                        tostring(currentRole or "Unknown")
                    ),
                    inline = true
                },
                {
                    name = "⏱️ Session Time",
                    value = "\`" .. uptime .. "\`",
                    inline = false
                }
            },
            footer = { text = "A&H HUB • Premium Auto-Farm" },
            timestamp = DateTime.now():ToIsoDate()
        }}
    }

    local success, mode = postWebhookPayload(data)
    if success then
        webhookMark(true, mode)
return true
    end
    webhookMark(false, "balance delivery failed")
    return false

end

