local function updateCharacterParts()
    characterParts = {}
    if not character then return end
    for _, part in ipairs(character:GetDescendants()) do
        if part:IsA("BasePart") then
            table.insert(characterParts, part)
        end
    end
end

local function restoreCollision() 
    for _, part in ipairs(characterParts) do 
        if part and part.Parent then 
            part.CanCollide = true 
        end 
    end 
end 


local function getRoleTool(role)
    local wanted = role == "Murderer" and "knife" or role == "Sheriff" and "gun"
    if not wanted then return nil end

    local containers = {character, player:FindFirstChildOfClass("Backpack")}
    for _, container in ipairs(containers) do
        if container then
            for _, obj in ipairs(container:GetChildren()) do
                if obj:IsA("Tool") and obj.Name:lower():find(wanted, 1, true) then
                    return obj
                end
            end
        end
    end
    return nil
end

