local function updateRoundState(state)
    roundState = state or "WAITING"
    if dashboardStateLabel and dashboardStateLabel.Parent then
        dashboardStateLabel.Text = "State: " .. roundState
    end
    if dashboardRoundLabel and dashboardRoundLabel.Parent then
        dashboardRoundLabel.Text = "Round: " .. tostring(roundNumber or 0)
    end
    if dashboardTargetLabel and dashboardTargetLabel.Parent then
        dashboardTargetLabel.Text = "Target: " .. (currentTarget and currentTarget.Name or "None")
    end
    debugLog("Round state -> " .. roundState)
end

local function resetTemporaryFarmState(nextState)
    roleActionBusy = false
    roleResetGeneration += 1
    bagIsFull = false
    isWaitingForCoins = true
    coinsReady = false
    currentTarget = nil
    activeCoins = {}
    blacklistedCoins = {}
    noCoinsStartTime = nil
    local movementReady = type(stopMovement) == "function"
    local noclipReady = type(stopNoclip) == "function"
    if movementReady then pcall(stopMovement) end
    if noclipReady then pcall(stopNoclip) end
    if not movementReady or not noclipReady then
        task.defer(function()
            if type(stopMovement) == "function" then pcall(stopMovement) end
            if type(stopNoclip) == "function" then pcall(stopNoclip) end
        end)
    end
    if nextState then updateRoundState(nextState) end
end

local function applyRoleProfile(role, announce)
    local profile = roleProfiles[role] or roleProfiles.Unknown
    TARGET_SPEED = math.min(tonumber(profile.speed) or MAX_SAFE_FARM_SPEED, MAX_SAFE_FARM_SPEED)
    currentRole = role or "Unknown"
    if dashboardRoleLabel and dashboardRoleLabel.Parent then
        dashboardRoleLabel.Text = "Role: " .. currentRole
    end
    if announce then debugLog("Role profile -> " .. currentRole .. " (speed " .. tostring(profile.speed) .. ")") end
    return profile
end

local function normalizeRoleValue(value)
    if value == nil then return nil end
    local text = tostring(value):gsub("^%s+", ""):gsub("%s+$", "")
    if text == "" then return nil end
    local lower = text:lower()
    local known = {
        murderer = "Murderer",
        sheriff = "Sheriff",
        innocent = "Innocent",
        hero = "Hero",
        detective = "Detective",
    }
    return known[lower] or text
end

local function getRoleFromDataSource()
    local role = normalizeRoleValue(player:GetAttribute("Role"))
        or normalizeRoleValue(player:GetAttribute("role"))
        or normalizeRoleValue(player:GetAttribute("CurrentRole"))
        or normalizeRoleValue(player:GetAttribute("currentRole"))
    if role then return role end

    for _, container in ipairs({player, character}) do
        if container then
            local roleObject = container:FindFirstChild("Role", true) or container:FindFirstChild("role", true)
            if roleObject and (roleObject:IsA("StringValue") or roleObject:IsA("ObjectValue")) then
                role = normalizeRoleValue(roleObject.Value)
                if role then return role end
            end
        end
    end

    return nil
end

local function detectRole()
    -- Prefer the game's explicit role data. Tool detection is only a fallback
    -- for rounds where the attribute/value has not replicated yet.
    local dataRole = getRoleFromDataSource()
    if dataRole then return dataRole end
    if getRoleTool("Murderer") then return "Murderer" end
    if getRoleTool("Sheriff") then return "Sheriff" end
    return "Unknown"
end

local function updateRoleDisplay(role)
    local normalized = normalizeRoleValue(role) or "Unknown"
    local changed = normalized ~= currentRole
    applyRoleProfile(normalized, changed)
    if roleDisplayLabel and roleDisplayLabel.Parent then
        roleDisplayLabel.Text = "Role: " .. currentRole
    end
    if changed then
        resetTemporaryFarmState("ROUND STARTING")
        local profile = roleProfiles[currentRole] or roleProfiles.Unknown
        if currentRole == "Murderer" and profile.resetOnRoleAction then
            debugLog("Murderer profile armed; temporary farm state reset")
        end
        if sendWebhookEvent and webhookNotifyRoleChange then
            task.spawn(function() sendWebhookEvent("ROLE CHANGE") end)
        end
    end
end

local function findMurderer()
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= player then
            local char = plr.Character
            if char then
                for _, obj in ipairs(char:GetChildren()) do
                    if obj:IsA("Tool") and obj.Name:lower():find("knife", 1, true) then
                        return plr
                    end
                end

                local role = plr:GetAttribute("Role") or plr:GetAttribute("role")
                if typeof(role) == "string" and role:lower() == "murderer" then
                    return plr
                end
            end
        end
    end
    return nil
end

local function resetWhenKnifeGiven()
    if roleActionBusy or currentRole ~= "Murderer" then return end
    if not character or not humanoid or humanoid.Health <= 0 then return end
    if not getRoleTool("Murderer") then return end

    roleActionBusy = true
    local generation = roleResetGeneration
    stopMovement()
    stopNoclip()

    task.wait(0.15)
    if generation ~= roleResetGeneration then
        roleActionBusy = false
        return
    end
    if humanoid and humanoid.Parent and humanoid.Health > 0 and currentRole == "Murderer" then
        pcall(function() humanoid.Health = 0 end)
    else
        roleActionBusy = false
    end
end

local function sheriffAutoKill()
    if roleActionBusy or currentRole ~= "Sheriff" then return end

    local murderer = findMurderer()
    if not murderer or not murderer.Character then return end

    local targetRoot = murderer.Character:FindFirstChild("HumanoidRootPart")
    local myRoot = rootPart
    local gun = getRoleTool("Sheriff")
    if not targetRoot or not myRoot or not gun then return end

    if (targetRoot.Position - myRoot.Position).Magnitude > SHERIFF_MAX_RANGE then
        return
    end

    roleActionBusy = true
    local oldCFrame = myRoot.CFrame

    myRoot.CFrame = CFrame.lookAt(myRoot.Position, targetRoot.Position)

    if gun.Parent ~= character and humanoid then
        humanoid:EquipTool(gun)
        task.wait()
    end

    -- Uses the normal sheriff Tool activation rather than an invented
    -- server RemoteEvent, so it remains compatible with the game's weapon API.
    for _ = 1, 8 do
        if not murderer.Parent or not murderer.Character then break end
        targetRoot = murderer.Character:FindFirstChild("HumanoidRootPart")
        if not targetRoot then break end

        myRoot.CFrame = CFrame.lookAt(myRoot.Position, targetRoot.Position)
        pcall(function()
            gun:Activate()
        end)
        task.wait(SHERIFF_FIRE_INTERVAL)
    end

    if myRoot and myRoot.Parent and humanoid and humanoid.Health > 0 then
        myRoot.CFrame = oldCFrame
    end

    roleActionBusy = false
end

local function startRoleMonitor()
    if roleMonitorThread then
        task.cancel(roleMonitorThread)
        roleMonitorThread = nil
    end

    roleMonitorThread = task.spawn(function()
        while isLoaded and enabled do
            if player and player.Parent and character and humanoid and humanoid.Health > 0 then
                local detectedRole = detectRole()
                if detectedRole ~= currentRole then
                    roleActionBusy = false
                    lastDetectedRole = detectedRole
                end
                updateRoleDisplay(detectedRole)

                local profile = roleProfiles[currentRole] or roleProfiles.Unknown
                if currentRole == "Murderer" and profile.resetOnRoleAction then
                    resetWhenKnifeGiven()
                elseif currentRole == "Sheriff" and profile.autoKill then
                    sheriffAutoKill()
                else
                    roleActionBusy = false
                end
            end

            task.wait(ROLE_SCAN_INTERVAL)
        end

        roleMonitorThread = nil
    end)
end

local function cleanupConnections() 
    if heartbeatConnection then heartbeatConnection:Disconnect() heartbeatConnection = nil end 
    if noclipConnection then noclipConnection:Disconnect() noclipConnection = nil end 
    if coinAddedConnection then coinAddedConnection:Disconnect() coinAddedConnection = nil end 
    if coinRemovedConnection then coinRemovedConnection:Disconnect() coinRemovedConnection = nil end 
    if coinsStartedConnection then coinsStartedConnection:Disconnect() coinsStartedConnection = nil end 
    if coinCollectedConnection then coinCollectedConnection:Disconnect() coinCollectedConnection = nil end 
end 

local function stopMovement() 
    if linearVelocity then 
        linearVelocity.VectorVelocity = Vector3.zero 
        linearVelocity.Enabled = false 
    end 
    if rootPart then 
        rootPart.AssemblyLinearVelocity = Vector3.zero 
        rootPart.AssemblyAngularVelocity = Vector3.zero 
    end 
end 

local function setupVelocity() 
    if not rootPart then return end 

    velocityAttachment = rootPart:FindFirstChild("FarmAttachment") 
    if not velocityAttachment then 
        velocityAttachment = Instance.new("Attachment") 
        velocityAttachment.Name = "FarmAttachment" 
        velocityAttachment.Parent = rootPart 
    end 

    linearVelocity = rootPart:FindFirstChild("FarmLinearVelocity") 
    if not linearVelocity then 
        linearVelocity = Instance.new("LinearVelocity") 
        linearVelocity.Name = "FarmLinearVelocity" 
        linearVelocity.Attachment0 = velocityAttachment 
        linearVelocity.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector 
        linearVelocity.RelativeTo = Enum.ActuatorRelativeTo.World 
        linearVelocity.VectorVelocity = Vector3.zero 
        linearVelocity.Enabled = false 
        linearVelocity.ForceLimitMode = Enum.ForceLimitMode.Magnitude 
        linearVelocity.MaxForce = 1000000000 
        linearVelocity.Parent = rootPart 
    end 
end 

local function removeVelocity() 
    if linearVelocity then linearVelocity:Destroy() linearVelocity = nil end 
    if velocityAttachment then velocityAttachment:Destroy() velocityAttachment = nil end 
end 

local function startNoclip()
    if noclipConnection then noclipConnection:Disconnect() end
    updateCharacterParts()
    local nextPartRefresh = 0

    noclipConnection = RunService.Stepped:Connect(function()
        if not (character and enabled and humanoid and humanoid.Health > 0 and not bagIsFull) then
            return
        end
        -- Refresh descendants so newly-created accessories/body parts cannot
        -- reintroduce collision while the farm is moving vertically.
        local now = os.clock()
        if #characterParts == 0 or now >= nextPartRefresh then
            updateCharacterParts()
            nextPartRefresh = now + 0.25
        end
        for i = 1, #characterParts do
            local part = characterParts[i]
            if part and part.Parent and part:IsA("BasePart") and part.CanCollide then
                part.CanCollide = false
            end
        end
    end)

    if humanoid then 
        humanoid:SetStateEnabled(Enum.HumanoidStateType.Climbing, false) 
        humanoid:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false) 
        humanoid:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false) 
        humanoid:SetStateEnabled(Enum.HumanoidStateType.Physics, false) 
    end 
end 

local function stopNoclip() 
    if noclipConnection then 
        noclipConnection:Disconnect() 
        noclipConnection = nil 
    end 
    restoreCollision() 
end 

local function antiAfkLoop() 
    while afkActive and enabled do 
        task.wait(30) 
        if not afkActive or not enabled then break end 
        VirtualUser:CaptureController() 
        VirtualUser:ClickButton2(Vector2.new()) 
    end 
end 

local function isCoin(part)
    if not part or not part:IsA("BasePart") or blacklistedCoins[part] then
        return false
    end

    local name = part.Name:lower()
    local namedCoin =
        name:find("coin", 1, true)
        or name:find("cash", 1, true)
        or name:find("money", 1, true)
        or name:find("collect", 1, true)

    if not namedCoin then
        return false
    end

    -- Only target visible, physical collectible parts.
    -- This prevents decorative/template objects high above the map
    -- from becoming movement targets before the real coins spawn.
    if part.Transparency >= 1 then
        return false
    end

    return part.Size.Magnitude > 0.05
end
local function checkGuiBagFull() 
    local playerGui = player:FindFirstChild("PlayerGui") 
    if not playerGui then return false end 

    for _, gui in ipairs(playerGui:GetChildren()) do 
        if gui:IsA("ScreenGui") and gui.Name ~= "AutoFarmUI" then 
            local container = gui:FindFirstChild("Container", true) 
            if container then 
                for _, frame in ipairs(container:GetChildren()) do 
                    if frame:IsA("Frame") and frame.Visible then 
                        local fullIcon = frame:FindFirstChild("FullBagIcon", true) 
                        local fullText = frame:FindFirstChild("Full", true) 
                        if (fullIcon and fullIcon.Visible) or (fullText and fullText.Visible) then 
                            return true 
                        end 
                    end 
                end 
            end 
        end 
    end 
    return false 
end 

local function trackCoin(part)
    if isCoin(part) then
        activeCoins[part] = true
        coinsReady = true
        if roundState == "WAITING" or roundState == "ROUND STARTING" then updateRoundState("FARMING") end
    end
end 

local function untrackCoin(part) 
    activeCoins[part] = nil 
    if currentTarget == part then 
        currentTarget = nil 
    end 
end 

local function triggerBagFullReset() 
    if bagIsFull then return end 
    bagIsFull = true 
    stopMovement() 
    stopNoclip() 

    task.wait(0.2) 
    if humanoid and humanoid.Health > 0 then 
        humanoid.Health = 0 
    end 
end 

local function initCoinListeners()
    activeCoins = {}

    coinsReady = false
    for _, v in ipairs(Workspace:GetDescendants()) do
        if isCoin(v) then
            activeCoins[v] = true
            coinsReady = true
        end
    end

    coinAddedConnection = Workspace.DescendantAdded:Connect(trackCoin)
    coinRemovedConnection = Workspace.DescendantRemoving:Connect(untrackCoin)

    if gameplayRemotes then
        local coinsStartedRemote = gameplayRemotes:WaitForChild("CoinsStarted", 5)
        local coinCollectedRemote = gameplayRemotes:WaitForChild("CoinCollected", 5)

        if coinsStartedRemote then
            coinsStartedRemote.OnClientEvent:Connect(function()
                roundNumber += 1
                pcall(resetTemporaryFarmState, "ROUND STARTING")
                debugLog("Round " .. tostring(roundNumber) .. " started")
                if webhookNotifyRoundStart and sendWebhookEvent then task.spawn(function() sendWebhookEvent("ROUND START") end) end

                -- Do NOT read the balance at round start.
                -- The old code captured the balance before collecting the round,
                -- which caused the webhook to report the previous amount.
                -- The balance is now captured when the bag/round actually finishes.

                isWaitingForCoins = true
                coinsReady = false
                stopMovement()
                currentTarget = nil
                activeCoins = {}
                blacklistedCoins = {}
                noCoinsStartTime = nil
                bagIsFull = false

                -- Stay completely still until actual coin parts exist.
                task.wait(ROUND_START_DELAY)

                local deadline = os.clock() + COIN_SPAWN_TIMEOUT
                repeat
                    for _, v in ipairs(Workspace:GetDescendants()) do
                        if isCoin(v) then
                            activeCoins[v] = true
                            coinsReady = true
                        end
                    end
                    if coinsReady then break end
                    task.wait(0.1)
                until os.clock() >= deadline or not isLoaded or not enabled

                isWaitingForCoins = not coinsReady
                updateRoundState(coinsReady and "FARMING" or "WAITING")
            end)
        end

        if coinCollectedRemote then
            coinCollectedConnection = coinCollectedRemote.OnClientEvent:Connect(function(coinType, currentAmount, maxAmount)
                local current = tonumber(currentAmount)
                local max = tonumber(maxAmount)
                if current and max and current >= max then
                    -- Give the game's GUI/account value a moment to update,
                    -- then read the NEW balance and send that value.
                    triggerBagFullReset()
                    updateRoundState("BAG FULL")
                    if webhookNotifyBagFull and sendWebhookEvent then task.spawn(function() sendWebhookEvent("BAG FULL") end) end
                    if webhookNotifyRoundEnd and sendWebhookEvent then task.spawn(function() sendWebhookEvent("ROUND END") end) end

                    task.spawn(function()
                        task.wait(1)

                        local balance = getBalance()
                        if balance ~= nil then
                            local delay = math.random(1, 5)
task.wait(delay)

                            -- Re-read after the delay so we never send a stale
                            -- balance captured before the round finished.
                            local latestBalance = getBalance() or balance
                            sendBalance(roundNumber, latestBalance)
                        else
                            return
                        end
                    end)
                end
            end)
        end
    end
end

local HEARTBEAT_INTERVAL = 1
local MONITOR_URL = "http://127.0.0.1:5000/heartbeat"

local function sendHeartbeat()
    local req = getRequestFunction()

    if not req then
        warn("❌ No HTTP request function available")
        return false
    end

    local elapsed = os.time() - injectedAt
    local uptime = string.format(
        "%02d:%02d:%02d",
        math.floor(elapsed / 3600),
        math.floor((elapsed % 3600) / 60),
        elapsed % 60
    )

    local currentBalance = getBalance()

    local data = {
        username = player.Name,
        displayName = player.DisplayName,
        userId = player.UserId,
        round = roundNumber,
        uptime = uptime,
        connected = true,
        coins = currentBalance,
        balance = currentBalance
    }

    local success, response = pcall(function()
        return req({
            Url = MONITOR_URL,
            Method = "POST",
            Headers = {
                ["Content-Type"] = "application/json"
            },
            Body = HttpService:JSONEncode(data)
        })
    end)

    if not success then
        warn("❌ Heartbeat failed:", response)
        return false
    end

    return true
end

-- Periodic webhook status/update loop. It is intentionally quiet when no valid URL is configured.
task.spawn(function()
    while true do
        task.wait(math.max(15, webhookInterval))
        if webhookEnabled and isValidWebhookURL(WEBHOOK_URL) then
            local balance = getBalance()
            if balance ~= nil and webhookNotifyBalance then
                pcall(sendBalance, roundNumber, balance)
            end
        end
    end
end)

-- Send immediately when the script starts.
task.spawn(function()
    -- Give LocalPlayer/HTTP environment a moment to initialize.
    task.wait(0.1)

    -- Immediate registration.
    sendHeartbeat()

    -- Continue sending every second.
    while true do
        task.wait(HEARTBEAT_INTERVAL)

        if not player or not player.Parent then
            break
        end

        sendHeartbeat()
    end
end)

local TARGET_SCAN_INTERVAL = 0.08
local FAST_TARGET_SCAN_INTERVAL = 0.05
local FAST_REACH_DISTANCE = 0.82
local FAST_NEAR_DISTANCE = 5.5
local FAST_BRAKE_MIN_SPEED = 3.0

local function refreshCoinCache()
    if not activeCoins then activeCoins = {} end
    local found = false
    for _, v in ipairs(Workspace:GetDescendants()) do
        if isCoin(v) then
            activeCoins[v] = true
            found = true
        end
    end
    if found then
        coinsReady = true
        isWaitingForCoins = false
    end
    return found
end

local function startTargetFinder()
    if targetFinderThread then
        task.cancel(targetFinderThread)
        targetFinderThread = nil
    end

    targetFinderThread = task.spawn(function()
        while isLoaded and enabled do
            if humanoid and humanoid.Health > 0 and rootPart and rootPart.Parent and not bagIsFull then
                -- Never gate discovery on CoinsStarted. MM2 can create/reparent
                -- coin parts without the client receiving that round signal.
                refreshCoinCache()

                local nearest = nil
                local nearestDistance = MAX_DIST
                local direct = nil
                local directDistance = MAX_DIST
                local rootPos = rootPart.Position

                for coin in pairs(activeCoins) do
                    if not coin or not coin.Parent or blacklistedCoins[coin] or not isCoin(coin) then
                        activeCoins[coin] = nil
                    else
                        local delta = coin.Position - rootPos
                        local distance = delta.Magnitude
                        if distance < nearestDistance then
                            nearest = coin
                            nearestDistance = distance
                        end
                        if currentProfileName == "Fast Farm" and distance < directDistance then
                            local rayParams = RaycastParams.new()
                            rayParams.FilterType = Enum.RaycastFilterType.Exclude
                            rayParams.FilterDescendantsInstances = {character}
                            rayParams.IgnoreWater = true
                            local hit = Workspace:Raycast(rootPos, delta, rayParams)
                            if not hit or hit.Instance == coin or hit.Instance:IsDescendantOf(coin) then
                                direct = coin
                                directDistance = distance
                            end
                        end
                    end
                end

                currentTarget = direct or nearest
                if nearest then
                    coinsReady = true
                    isWaitingForCoins = false
                    if roundState ~= "FARMING" then updateRoundState("FARMING") end
                end
            else
                currentTarget = nil
            end

            task.wait((currentProfileName == "Fast Farm") and FAST_TARGET_SCAN_INTERVAL or TARGET_SCAN_INTERVAL)
        end
        targetFinderThread = nil
    end)
end

local function startMovementEngine()
    cleanupConnections()
    setupVelocity()
    initCoinListeners()
    noCoinsStartTime = nil

    heartbeatConnection = RunService.Heartbeat:Connect(function()
        if not enabled or bagIsFull or not rootPart or not rootPart.Parent
            or not humanoid or humanoid.Health <= 0 then
            stopMovement()
            if noclipConnection then stopNoclip() end
            return
        end

        -- Discovery is authoritative; do not require a remote-driven waiting state.
        if not currentTarget or not currentTarget.Parent or blacklistedCoins[currentTarget] or not isCoin(currentTarget) then
            refreshCoinCache()
            local nearest, nearestDistance = nil, MAX_DIST
            local rootPos = rootPart.Position
            for coin in pairs(activeCoins) do
                if not coin or not coin.Parent or blacklistedCoins[coin] or not isCoin(coin) then
                    activeCoins[coin] = nil
                else
                    local distance = (coin.Position - rootPos).Magnitude
                    if distance < nearestDistance then
                        nearest, nearestDistance = coin, distance
                    end
                end
            end
            currentTarget = nearest
        end

        if currentTarget and currentTarget.Parent and not blacklistedCoins[currentTarget] then
            isWaitingForCoins = false
            coinsReady = true
            noCoinsStartTime = nil
            if not noclipConnection then startNoclip() end

            -- Keep the character non-collidable at the exact point where movement
            -- is applied as well as in the Stepped noclip pass. This is important
            -- when descending through floors/ramps because the physics solver can
            -- otherwise re-enable collision for a frame.
            if characterParts then
                for i = 1, #characterParts do
                    local part = characterParts[i]
                    if part and part.Parent and part:IsA("BasePart") then
                        part.CanCollide = false
                    end
                end
            end
            if rootPart then rootPart.CanCollide = false end

            local targetPos = currentTarget.Position
            local offset = targetPos - rootPart.Position
            local dist = offset.Magnitude

            -- Do not consider the coin collected merely because the player is
            -- close to it. Fast movement can carry the character past a small
            -- pickup radius before the next Heartbeat. Converge on the actual
            -- center point and only switch once we are genuinely on top of it.
            local reachDistance = (currentProfileName == "Fast Farm") and FAST_REACH_DISTANCE or 0.65
            if dist <= reachDistance then
                -- Switch targets immediately after reaching the coin center.
                -- Do not zero the character for a frame and do not wait in the air;
                -- the next valid coin becomes the target in the same heartbeat.
                local reached = currentTarget
                blacklistedCoins[reached] = true
                activeCoins[reached] = nil
                currentTarget = nil

                local nextTarget, nextDistance = nil, MAX_DIST
                local refreshedRoot = rootPart.Position
                for coin in pairs(activeCoins) do
                    if coin and coin.Parent and not blacklistedCoins[coin] and isCoin(coin) then
                        local d = (coin.Position - refreshedRoot).Magnitude
                        if d < nextDistance then
                            nextTarget, nextDistance = coin, d
                        end
                    else
                        activeCoins[coin] = nil
                    end
                end
                currentTarget = nextTarget
                if not currentTarget then
                    refreshCoinCache()
                    for coin in pairs(activeCoins) do
                        if coin and coin.Parent and not blacklistedCoins[coin] and isCoin(coin) then
                            local d = (coin.Position - refreshedRoot).Magnitude
                            if d < nextDistance then
                                currentTarget, nextDistance = coin, d
                            end
                        end
                    end
                end
            else
                local safeSpeed = math.min(math.max(0, tonumber(TARGET_SPEED) or MAX_SAFE_FARM_SPEED), MAX_SAFE_FARM_SPEED)
                -- Fast mode used to travel at full speed right up to the pickup
                -- point. That can overshoot the coin, especially when moving
                -- vertically. Use a short, distance-based braking zone so the
                -- final approach converges on the coin's actual center instead
                -- of passing beside it.
                local approachSpeed = safeSpeed
                if currentProfileName == "Fast Farm" and dist < FAST_NEAR_DISTANCE then
                    approachSpeed = math.min(safeSpeed, math.max(FAST_BRAKE_MIN_SPEED, dist * 7.5))
                elseif dist < 6 then
                    approachSpeed = math.min(safeSpeed, math.max(2.5, dist * 7))
                end
                local velocity = offset.Unit * approachSpeed
                if linearVelocity then
                    linearVelocity.VectorVelocity = velocity
                    linearVelocity.Enabled = true
                end
                -- Keep the physics velocity synchronized as a fallback, especially
                -- for vertical travel where Humanoid floor resolution can otherwise
                -- briefly cancel the LinearVelocity.
                rootPart.AssemblyLinearVelocity = velocity
                if math.abs(offset.Y) > 1.5 and humanoid then
                    pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Freefall) end)
                end
                -- Let the humanoid/physics controller handle facing. Rewriting
                -- CFrame every heartbeat can look like an invalid-position update
                -- to MM2's movement validation.
                if humanoid then humanoid.AutoRotate = true end
            end
        else
            stopMovement()
            if noclipConnection then stopNoclip() end
            noCoinsStartTime = noCoinsStartTime or os.clock()
            -- Keep scanning indefinitely. A missing coin for a few seconds is
            -- normal between rounds and must not deadlock the farm.
            if os.clock() - noCoinsStartTime > RESET_DELAY then
                coinsReady = false
                isWaitingForCoins = true
                refreshCoinCache()
                noCoinsStartTime = nil
            end
        end
    end)
end


local function unloadScript()
    isLoaded = false
    enabled = false
    afkActive = false
    bagIsFull = false
    isWaitingForCoins = false

    cleanupConnections()
    if roleMonitorThread then
        pcall(function() task.cancel(roleMonitorThread) end)
        roleMonitorThread = nil
    end
    for _, connection in ipairs(roleAttributeConnections) do
        pcall(function() connection:Disconnect() end)
    end
    table.clear(roleAttributeConnections)
    stopNoclip()
    removeVelocity()

    if targetFinderThread then
        task.cancel(targetFinderThread)
        targetFinderThread = nil
    end
    if characterAddedConnection then
        characterAddedConnection:Disconnect()
        characterAddedConnection = nil
    end

    activeCoins = {}
    blacklistedCoins = {}
    currentTarget = nil
end

local function loadScript()
    if isLoaded then unloadScript() end
    isLoaded = true
    bagIsFull = false
    isWaitingForCoins = false
    coinsReady = false

    character = player.Character or player.CharacterAdded:Wait()
    rootPart = character:WaitForChild("HumanoidRootPart")
    humanoid = character:WaitForChild("Humanoid")

    blacklistedCoins = {}
    noCoinsStartTime = nil
    hasCollectedThisLife = false

    startMovementEngine()
    startTargetFinder()
    startRoleMonitor()

    if characterAddedConnection then characterAddedConnection:Disconnect() end
    characterAddedConnection = player.CharacterAdded:Connect(function(newChar)
        cleanupConnections()
        removeVelocity()

        character = newChar
        roleActionBusy = false
        lastDetectedRole = "Unknown"
        roleResetGeneration += 1
        rootPart = character:WaitForChild("HumanoidRootPart")
        humanoid = character:WaitForChild("Humanoid")

        blacklistedCoins = {} 
        noCoinsStartTime = nil
        hasCollectedThisLife = false 
        bagIsFull = false
        isWaitingForCoins = false
        coinsReady = false
        updateRoundState("ROUND END")

        task.wait(0.25)
        if isLoaded and enabled then updateRoundState("WAITING") end
        if isLoaded and enabled then
            startMovementEngine()
            startTargetFinder()
            startRoleMonitor()
        end
    end)
end

