local function MakeDraggable(topbarobject, object)
    local dragging = false
    local dragStart = nil
    local startOffset = nil
    local targetOffset = Vector2.zero
    local renderConnection
    local inputChangedConnection
    local endedConnection

    local function viewportSize()
        local camera = Workspace.CurrentCamera
        return (camera and camera.ViewportSize) or Vector2.new(1920, 1080)
    end

    local function clampOffset(offset)
        local viewport = viewportSize()
        local halfW = math.max(0, object.AbsoluteSize.X * 0.5)
        local halfH = math.max(0, object.AbsoluteSize.Y * 0.5)
        local margin = 8
        local maxX = math.max(0, viewport.X * 0.5 - halfW - margin)
        local maxY = math.max(0, viewport.Y * 0.5 - halfH - margin)
        return Vector2.new(math.clamp(offset.X, -maxX, maxX), math.clamp(offset.Y, -maxY, maxY))
    end

    local function currentOffset()
        return Vector2.new(object.Position.X.Offset, object.Position.Y.Offset)
    end

    local function isInteractiveDescendant(guiObject)
        local node = guiObject
        while node and node ~= topbarobject do
            if node:IsA("TextButton") or node:IsA("ImageButton") or node:IsA("TextBox") then
                return true
            end
            node = node.Parent
        end
        return false
    end

    local function stopDragging()
        dragging = false
        dragStart = nil
        startOffset = nil
    end

    topbarobject.InputBegan:Connect(function(input)
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
            return
        end
        -- Do not let the drag handler steal clicks from close controls.
        local mousePos = Vector2.new(input.Position.X, input.Position.Y)
        for _, child in ipairs(topbarobject:GetChildren()) do
            if child:IsA("GuiButton") and child.Visible then
                local pos, size = child.AbsolutePosition, child.AbsoluteSize
                if mousePos.X >= pos.X and mousePos.X <= pos.X + size.X and mousePos.Y >= pos.Y and mousePos.Y <= pos.Y + size.Y then
                    return
                end
            end
        end

        dragging = true
        dragStart = input.Position
        startOffset = clampOffset(currentOffset())
        targetOffset = startOffset

        input.Changed:Connect(function()
            if input.UserInputState == Enum.UserInputState.End then
                stopDragging()
            end
        end)
    end)

    inputChangedConnection = topbarobject.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            if dragging then
                -- Store the most recent pointer input; RenderStepped performs the actual glide.
                endedConnection = input
            end
        end
    end)

    local globalChanged = UserInputService.InputChanged:Connect(function(input)
        if not dragging or not dragStart then return end
        if input.UserInputType ~= Enum.UserInputType.MouseMovement and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local delta = Vector2.new(input.Position.X - dragStart.X, input.Position.Y - dragStart.Y)
        targetOffset = clampOffset(startOffset + delta)
    end)

    renderConnection = RunService.RenderStepped:Connect(function(dt)
        if not object or not object.Parent then
            if renderConnection then renderConnection:Disconnect() end
            if inputChangedConnection then inputChangedConnection:Disconnect() end
            if globalChanged then globalChanged:Disconnect() end
            return
        end
        local current = clampOffset(currentOffset())
        local alpha = 1 - math.exp(-math.min(math.max(dt, 0), 0.05) * 22)
        local nextOffset = current:Lerp(clampOffset(targetOffset), alpha)
        if (nextOffset - current).Magnitude > 0.01 then
            object.Position = UDim2.new(0.5, nextOffset.X, 0.5, nextOffset.Y)
        end
    end)

    return stopDragging
end

local function getGuiParent()
    local ok, hui = pcall(function() return gethui and gethui() end)
    if ok and hui then return hui end
    return game:GetService("CoreGui")
end

