	local FullSize = UDim2.fromOffset(681, 396)
	local MiniSize = UDim2.fromOffset(58, 58)
	local MiniTween = TweenInfo.new(0.34, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
    local minimizeTween = nil
    local transitionId = 0
    local contentVisibility = {}

    local function isVisibleGuiObject(obj)
        return obj and obj:IsA("GuiObject") and obj ~= MinimizedOrb and obj ~= MinimizeBtn
    end

    local function saveContentVisibility()
        contentVisibility = {}
        for _, child in ipairs(MainFrame:GetChildren()) do
            if isVisibleGuiObject(child) then
                contentVisibility[child] = child.Visible
            end
        end
    end

    local function restoreContentVisibility()
        for child, wasVisible in pairs(contentVisibility) do
            if child and child.Parent == MainFrame then
                pcall(function() child.Visible = wasVisible end)
            end
        end
        if UIThemeState.refreshTabs then UIThemeState.refreshTabs() end
    end

    local function setContentVisible(visible)
        for _, child in ipairs(MainFrame:GetChildren()) do
            if isVisibleGuiObject(child) then
                child.Visible = visible
            end
        end
    end

    local function setMinimized(state)
        if not MainFrame or not MainFrame.Parent or not MinimizedOrb or not MinimizedOrb.Parent then return end
        transitionId += 1
        local thisTransition = transitionId
        minimized = state == true

        if minimizeTween then
            pcall(function() minimizeTween:Cancel() end)
            minimizeTween = nil
        end

        MainFrame.ClipsDescendants = true

        -- Blur belongs to the full UI only. The orb/minimized state must never
        -- leave a Lighting BlurEffect behind.
        if previousGlobal.__AH_HUB_UI and previousGlobal.__AH_HUB_UI.SetBlur then
            pcall(function() previousGlobal.__AH_HUB_UI.SetBlur(not minimized, uiBlurSize) end)
        end

        if minimized then
            saveContentVisibility()
            setContentVisible(false)
            MainFrame.Visible = true
            MinimizedOrb.Visible = false
            minimizeTween = TweenService:Create(MainFrame, MiniTween, {Size = MiniSize})
            local tween = minimizeTween
            tween.Completed:Connect(function()
                if thisTransition ~= transitionId or not minimized or not MainFrame.Parent then return end
                minimizeTween = nil
                MainFrame.Visible = false
                MinimizedOrb.Position = MainFrame.Position
                MinimizedOrb.Visible = true
            end)
            tween:Play()
        else
            MinimizedOrb.Visible = false
            MainFrame.Visible = true
            MainFrame.Size = MiniSize
            restoreContentVisibility()
            minimizeTween = TweenService:Create(MainFrame, MiniTween, {Size = FullSize})
            local tween = minimizeTween
            tween.Completed:Connect(function()
                if thisTransition ~= transitionId or minimized or not MainFrame.Parent then return end
                minimizeTween = nil
                MainFrame.Size = FullSize
                restoreContentVisibility()
            end)
            tween:Play()
        end
    end

    local uiController = {
        Toggle = function()
            if not MainFrame or not MainFrame.Parent then return end
            setMinimized(not minimized)
        end,
        Restore = function()
            if not MainFrame or not MainFrame.Parent then return end
            setMinimized(false)
        end,
        IsMinimized = function() return minimized end,
        SetScale = function(value)
            local scale = MainFrame:FindFirstChild("A_H_UI_Scale")
            if not scale then scale = Instance.new("UIScale"); scale.Name = "A_H_UI_Scale"; scale.Parent = MainFrame end
            scale.Scale = math.clamp(tonumber(value) or 100, 75, 125) / 100
        end,
        SetTransparency = function(value)
            -- Kept as a compatibility no-op for older saved settings. The UI
            -- transparency control was removed from Themes and no longer alters
            -- the visual surface opacity.
        end,
        SetBlur = function(enabledValue, size)
            pcall(function()
                local Lighting = game:GetService("Lighting")
                local blur = Lighting:FindFirstChild("A_H_HUB_UIBlur")
                local shouldEnable = enabledValue == true and not minimized
                if shouldEnable then
                    if not blur then
                        blur = Instance.new("BlurEffect")
                        blur.Name = "A_H_HUB_UIBlur"
                        blur.Parent = Lighting
                    end
                    blur.Size = math.clamp(tonumber(size) or 0, 0, 24)
                    blur.Enabled = blur.Size > 0
                elseif blur then
                    blur.Enabled = false
                    blur.Size = 0
                end
            end)
        end
    }
    previousGlobal.__AH_HUB_UI = uiController
    previousGlobal.__AH_HUB_CLEANUP = function()
        pcall(unloadScript)
        pcall(function()
            local Lighting = game:GetService("Lighting")
            local blur = Lighting:FindFirstChild("A_H_HUB_UIBlur")
            if blur then blur:Destroy() end
        end)
        previousGlobal.__AH_HUB_UI = nil
        previousGlobal.__AH_HUB_CLEANUP = nil
        if Discord and Discord.Parent then
            Discord:Destroy()
        end
    end
