					if ep then
						if #TextBox.Text > 0 then
							pcall(callback, TextBox.Text)
							if disapper then
								TextBox.Text = ""
							end
						end
					end
				end)
				
				ChannelHolder.CanvasSize = UDim2.new(0,0,0,ChannelHolderLayout.AbsoluteContentSize.Y)
			end
			
			function ChannelContent:Label(text)
				local Label = Instance.new("TextButton")
				local LabelTitle = Instance.new("TextLabel")

				Label.Name = "Label"
				Label.Parent = ChannelHolder
				Label.BackgroundColor3 = UIThemeState.colors.card
				Label.BackgroundTransparency = 1
				Label.BorderSizePixel = 0
                Label:SetAttribute("ThemeTransparent", true)
				Label.Position = UDim2.new(0.261979163, 0, 0.190789461, 0)
				Label.Size = UDim2.new(0, 401, 0, 30)
				Label.AutoButtonColor = false
				Label.Font = Enum.Font.Gotham
				Label.Text = ""
				Label.TextColor3 = Color3.fromRGB(255, 255, 255)
				Label.TextSize = 14.000

				LabelTitle.Name = "LabelTitle"
				LabelTitle.Parent = Label
                LabelTitle:SetAttribute("ThemeTextRole", "muted")
				LabelTitle.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
				LabelTitle.BackgroundTransparency = 1.000
				LabelTitle.Position = UDim2.new(0, 5, 0, 0)
				LabelTitle.Size = UDim2.new(0, 200, 0, 30)
				LabelTitle.Font = Enum.Font.Gotham
				LabelTitle.Text = text
				LabelTitle.TextColor3 = UIThemeState.colors.muted
				LabelTitle.TextSize = 14.000
				LabelTitle.TextXAlignment = Enum.TextXAlignment.Left
				
				ChannelHolder.CanvasSize = UDim2.new(0,0,0,ChannelHolderLayout.AbsoluteContentSize.Y)
                return LabelTitle
			end

                function ChannelContent:Image(name, asset, size)
                    local holder = Instance.new("Frame")
                    local image = Instance.new("ImageLabel")
                    local corner = Instance.new("UICorner")
                    holder.Name = name or "Image"
                    holder.Parent = ChannelHolder
                    holder.BackgroundTransparency = 1
                    holder.BorderSizePixel = 0
                    holder.Size = UDim2.new(0, 401, 0, size or 58)
                    image.Name = "Image"
                    image.Parent = holder
                    image.AnchorPoint = Vector2.new(0.5, 0.5)
                    image.Position = UDim2.fromScale(0.5, 0.5)
                    image.Size = UDim2.fromOffset(size or 58, size or 58)
                    image.BackgroundTransparency = 1
                    image.Image = asset or ""
                    image.ScaleType = Enum.ScaleType.Fit
                    corner.CornerRadius = UDim.new(0, 10)
                    corner.Parent = image
                    ChannelHolder.CanvasSize = UDim2.new(0,0,0,ChannelHolderLayout.AbsoluteContentSize.Y)
                    return image
                end
			
			function ChannelContent:Bind(text, presetbind, callback)
				local Key = presetbind.Name
				local Keybind = Instance.new("TextButton")
				local KeybindTitle = Instance.new("TextLabel")
				local KeybindText = Instance.new("TextLabel")

				Keybind.Name = "Keybind"
				Keybind.Parent = ChannelHolder
                -- Keybind rows are theme controls; never leave the old Discord-gray hardcoded.
                Keybind:SetAttribute("ThemeControl", true)
                Keybind:SetAttribute("ThemeCard", true)
				Keybind.BackgroundColor3 = UIThemeState.colors.card
				Keybind.BorderSizePixel = 0
				Keybind.Position = UDim2.new(0.261979163, 0, 0.190789461, 0)
				Keybind.Size = UDim2.new(0, 401, 0, 30)
				Keybind.AutoButtonColor = false
				Keybind.Font = Enum.Font.Gotham
				Keybind.Text = ""
				Keybind.TextColor3 = Color3.fromRGB(255, 255, 255)
				Keybind.TextSize = 14.000

				KeybindTitle.Name = "KeybindTitle"
				KeybindTitle.Parent = Keybind
                KeybindTitle:SetAttribute("ThemeTextRole", "muted")
				KeybindTitle.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
				KeybindTitle.BackgroundTransparency = 1.000
				KeybindTitle.Position = UDim2.new(0, 5, 0, 0)
				KeybindTitle.Size = UDim2.new(0, 200, 0, 30)
				KeybindTitle.Font = Enum.Font.Gotham
				KeybindTitle.Text = text
				KeybindTitle.TextColor3 = UIThemeState.colors.muted
                KeybindTitle:SetAttribute("ThemeTextRole", "muted")
				KeybindTitle.TextSize = 14.000
				KeybindTitle.TextXAlignment = Enum.TextXAlignment.Left

				KeybindText.Name = "KeybindText"
				KeybindText.Parent = Keybind
				KeybindText.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
				KeybindText.BackgroundTransparency = 1.000
				KeybindText.Position = UDim2.new(0, 316, 0, 0)
				KeybindText.Size = UDim2.new(0, 85, 0, 30)
				KeybindText.Font = Enum.Font.Gotham
				KeybindText.Text = presetbind.Name
				KeybindText.TextColor3 = UIThemeState.colors.muted
                KeybindText:SetAttribute("ThemeTextRole", "muted")
				KeybindText.TextSize = 14.000
				KeybindText.TextXAlignment = Enum.TextXAlignment.Right
				
				Keybind.MouseButton1Click:Connect(function()
					KeybindText.Text = "..."
					local inputwait = game:GetService("UserInputService").InputBegan:wait()
					if inputwait.KeyCode.Name ~= "Unknown" then
						KeybindText.Text = inputwait.KeyCode.Name
						Key = inputwait.KeyCode.Name
					end
				end)
				
				game:GetService("UserInputService").InputBegan:connect(
				function(current, pressed)
					if not pressed then
						if current.KeyCode.Name == Key then
							pcall(callback)
						end
					end
				end
				)
				ChannelHolder.CanvasSize = UDim2.new(0,0,0,ChannelHolderLayout.AbsoluteContentSize.Y)
			end
			
			return ChannelContent
		end
		
		return ChannelHold
	end
	return ServerHold
end

