    pcall(function() if writefile then writefile(PROFILE_FILE, tostring(name)) end end)
end
local function loadProfileName()
    local name = "Custom"
    pcall(function()
        if isfile and readfile and isfile(PROFILE_FILE) then name = tostring(readfile(PROFILE_FILE)):gsub("%s+", "") end
    end)
    return presetProfiles[name] and name or "Custom"
end
