local function saveUICustomization()
    pcall(function()
        if writefile and HttpService then
            writefile(UI_CUSTOM_FILE, HttpService:JSONEncode({scale=uiScaleValue, animation=uiAnimationIntensity, blur=uiBlurEnabled, blurSize=uiBlurSize, compact=compactMode, webhookInterval=webhookInterval}))
        end
    end)
end
local function loadUICustomization()
    pcall(function()
        if isfile and readfile and HttpService and isfile(UI_CUSTOM_FILE) then
            local data = HttpService:JSONDecode(readfile(UI_CUSTOM_FILE))
            if type(data) == "table" then
                uiScaleValue = tonumber(data.scale) or uiScaleValue
                uiAnimationIntensity = tonumber(data.animation) or uiAnimationIntensity
                if type(data.blurSize) == "number" then
                    uiBlurSize = math.clamp(data.blurSize, 0, 24)
                    uiBlurEnabled = uiBlurSize > 0
                else
                    uiBlurEnabled = data.blur == true
                    uiBlurSize = uiBlurEnabled and 4 or 0
                end
                compactMode = data.compact == true
                if data.webhookInterval ~= nil then
                    webhookInterval = math.clamp(math.floor(tonumber(data.webhookInterval) or webhookInterval), 15, 300)
                end
            end
        end
    end)
end
loadUICustomization()

