-- PREMIUM THEME SYSTEM
-- =========================================================
local THEME_FILE = "ahhub_theme.txt"
local THEMES = {
    ["Midnight"] = {bg=Color3.fromRGB(18,20,27), panel=Color3.fromRGB(25,28,38), card=Color3.fromRGB(32,35,48), accent=Color3.fromRGB(91,108,255), text=Color3.fromRGB(238,241,255), muted=Color3.fromRGB(150,157,178)},
    ["Crimson"] = {bg=Color3.fromRGB(25,17,21), panel=Color3.fromRGB(39,23,29), card=Color3.fromRGB(54,28,36), accent=Color3.fromRGB(235,65,89), text=Color3.fromRGB(255,239,242), muted=Color3.fromRGB(185,150,158)},
    ["Purple"] = {bg=Color3.fromRGB(23,18,31), panel=Color3.fromRGB(34,25,47), card=Color3.fromRGB(47,32,63), accent=Color3.fromRGB(166,91,255), text=Color3.fromRGB(245,237,255), muted=Color3.fromRGB(172,154,190)},
    ["Blue"] = {bg=Color3.fromRGB(15,22,31), panel=Color3.fromRGB(21,32,45), card=Color3.fromRGB(29,44,61), accent=Color3.fromRGB(54,155,255), text=Color3.fromRGB(235,247,255), muted=Color3.fromRGB(145,170,193)},
    ["Neon"] = {bg=Color3.fromRGB(10,18,19), panel=Color3.fromRGB(13,29,29), card=Color3.fromRGB(17,43,42), accent=Color3.fromRGB(47,255,187), text=Color3.fromRGB(232,255,248), muted=Color3.fromRGB(137,190,176)},
    ["Minimal"] = {bg=Color3.fromRGB(239,240,243), panel=Color3.fromRGB(248,249,251), card=Color3.fromRGB(229,231,235), accent=Color3.fromRGB(35,39,47), text=Color3.fromRGB(28,31,37), muted=Color3.fromRGB(100,106,116)},
    ["Premium"] = {bg=Color3.fromRGB(17,17,22), panel=Color3.fromRGB(27,25,32), card=Color3.fromRGB(40,36,48), accent=Color3.fromRGB(222,170,88), text=Color3.fromRGB(255,247,230), muted=Color3.fromRGB(177,165,145)}
}

local function loadThemeName()
    local name = "Midnight"
    pcall(function() if isfile and isfile(THEME_FILE) then name = readfile(THEME_FILE) end end)
    return THEMES[name] and name or "Midnight"
end

local function saveThemeName(name)
    pcall(function() if writefile then writefile(THEME_FILE, name) end end)
end

local activeThemeName = loadThemeName()
local function applyPremiumTheme(name)
    local t = THEMES[name]
    if not t then return end
    activeThemeName = name
    saveThemeName(name)
    UIThemeState.name = name
    UIThemeState.colors = {
        bg=t.bg, panel=t.panel, card=t.card, accent=t.accent, text=t.text, muted=t.muted,
        hover=t.card:Lerp(t.text, 0.08),
        active=t.card:Lerp(t.accent, 0.22),
        divider=t.card:Lerp(t.text, 0.16),
    }

    local root = Discord
    for _, obj in ipairs(root:GetDescendants()) do
        if obj:IsA("Frame") and obj.BackgroundTransparency < 1 then obj:SetAttribute("ThemeSurface", true) end
        pcall(function()
            if obj:IsA("Frame") or obj:IsA("ScrollingFrame") then
                if obj:GetAttribute("ThemeTransparent") == true then
                    obj.BackgroundTransparency = 1
                elseif obj.Name == "MainFrame" then
                    obj.BackgroundColor3 = t.bg
                elseif obj.Name == "NavigationDivider" then
                    obj.BackgroundColor3 = UIThemeState.colors.divider
                elseif obj.Name == "Userpad" then
                    obj.BackgroundColor3 = t.panel
                elseif obj.Name == "UserIcon" then
                    obj.BackgroundColor3 = t.bg
                elseif obj.BackgroundTransparency < 1 then
                    obj.BackgroundColor3 = t.panel
                end
            elseif obj:IsA("TextLabel") then
                if obj:GetAttribute("ThemeMuted") == true then
                    obj.TextColor3 = t.muted
                elseif obj:GetAttribute("AccountIdentifier") == true then
                    obj.TextColor3 = t.muted
                elseif obj.TextTransparency < 1 then
                    obj.TextColor3 = t.text
                end
            elseif obj:IsA("TextButton") then
                if obj:GetAttribute("ThemeTransparent") == true then
                    if obj.Name == "Label" then obj.BackgroundTransparency = 1 end
                    obj.BackgroundTransparency = 1
                elseif obj:GetAttribute("TabRole") == "Channel" or obj:GetAttribute("TabRole") == "Server" then
                    -- Navigation colors are refreshed below; never blanket-paint tabs.
                elseif obj:GetAttribute("ThemeControl") == true then
                    if obj.Name == "Toggle" then
                        obj.BackgroundColor3 = t.card
                        local title = obj:FindFirstChild("ToggleTitle")
                        if title then title.TextColor3 = t.text end
                    elseif obj.Name == "Button" then
                        obj.BackgroundColor3 = t.accent
                        obj.TextColor3 = t.text
                    else
                        obj.BackgroundColor3 = t.card
                        obj.TextColor3 = t.text
                    end
                elseif obj.Name == "PremiumMinimizedOrb" then
                    obj.BackgroundColor3 = t.accent
                elseif obj:GetAttribute("ThemeCard") == true then
                    obj.BackgroundColor3 = t.card
                    obj.TextColor3 = t.text
                end
            elseif obj:IsA("UIStroke") then
                if obj.Name == "AccountIdentifierStroke" then
                    obj.Color = UIThemeState.colors.divider
                else
                    obj.Color = t.accent
                    obj.Transparency = 0.78
                end
            elseif obj:IsA("ImageButton") then
                obj.ImageColor3 = t.text
            end
        end)
    end

    local orb = root:FindFirstChild("PremiumMinimizedOrb", true)
    local minIcon = nil
    if orb and orb:IsA("TextButton") then orb.BackgroundColor3 = t.accent end
    if minIcon and minIcon:IsA("ImageLabel") then minIcon.ImageColor3 = t.text end
    for _, obj in ipairs(root:GetDescendants()) do
        if obj:GetAttribute("ThemeControl") == true then
            if obj.Name == "Button" then
                obj.BackgroundColor3 = t.accent
                obj.TextColor3 = t.text
            elseif obj.Name == "Toggle" then
                obj.BackgroundColor3 = t.card
                local title = obj:FindFirstChild("ToggleTitle")
                if title then title.TextColor3 = t.text end
                local frame = obj:FindFirstChild("ToggleFrame")
                if frame then
                    local isOn = obj:GetAttribute("ToggleOn") == true
                    frame.BackgroundColor3 = isOn and t.accent or t.muted
                    local circle = frame:FindFirstChild("ToggleFrameCircle")
                    if circle then circle.Position = isOn and UDim2.new(0.655, -5, 0.133000001, 0) or UDim2.new(0.234999999, -5, 0.133000001, 0) end
                    local icon = circle and circle:FindFirstChild("Icon")
                    if icon then
                        icon.ImageColor3 = isOn and t.accent or t.muted
                        icon.Image = isOn and "http://www.roblox.com/asset/?id=6023426926" or "http://www.roblox.com/asset/?id=6035047409"
                        icon.ImageTransparency = 0
                    end
                end
            elseif obj.Name == "Slider" then
                obj.BackgroundColor3 = t.card
                local title = obj:FindFirstChild("SliderTitle")
                if title then title.TextColor3 = t.text end
                local valueFrame = obj:FindFirstChild("CurrentValueFrame")
                if valueFrame then valueFrame.BackgroundColor3 = t.accent end
                local sliderFrame = obj:FindFirstChild("SliderFrame")
                if sliderFrame then sliderFrame.BackgroundColor3 = t.card:Lerp(t.text, 0.16) end
                local zip = sliderFrame and sliderFrame:FindFirstChild("Zip")
                if zip then
                    zip.BackgroundColor3 = t.text
                    local bubble = zip:FindFirstChild("ValueBubble")
                    if bubble then bubble.BackgroundColor3 = t.card end
                    local valueLabel = bubble and bubble:FindFirstChild("ValueLabel")
                    if valueLabel then valueLabel.TextColor3 = t.text end
                end
            elseif obj.Name == "Dropdown" then
                local title = obj:FindFirstChild("DropdownTitle")
                if title then title.TextColor3 = t.text end
                local frame = title and title:FindFirstChild("DropdownFrame")
                if frame then frame.BackgroundColor3 = t.card end
                local outline = title and title:FindFirstChild("DropdownFrameOutline")
                if outline then outline.BackgroundColor3 = t.accent:Lerp(t.card, 0.55) end
                local selected = frame and frame:FindFirstChild("CurrentSelectedText")
                if selected then selected.TextColor3 = t.text end
            end
        end
    end
    if UIThemeState.refreshTabs then UIThemeState.refreshTabs() end
    if UIThemeState.refreshSettings then UIThemeState.refreshSettings() end
    if UIThemeState.refreshFeatureLabels then UIThemeState.refreshFeatureLabels() end
    if roleDisplayLabel and roleDisplayLabel.Parent then
        roleDisplayLabel.TextColor3 = t.text
    end
end

UIThemeState.refreshTabs = function()
    local root = Discord
    for _, obj in ipairs(root:GetDescendants()) do
        if obj:IsA("TextButton") and obj:GetAttribute("TabRole") then
            local selected = obj:GetAttribute("TabSelected") == true
            local hovered = obj:GetAttribute("TabHovered") == true
            obj.BackgroundColor3 = selected and UIThemeState.colors.active
                or (hovered and UIThemeState.colors.hover or UIThemeState.colors.card)
            obj.TextColor3 = UIThemeState.colors.text
            local title = obj:FindFirstChild("ChannelBtnTitle")
            if title and title:IsA("TextLabel") then
                title.TextColor3 = selected and UIThemeState.colors.text
                    or (hovered and UIThemeState.colors.text or UIThemeState.colors.muted)
            end
            local hashtag = obj:FindFirstChild("ChannelBtnHashtag")
            if hashtag and hashtag:IsA("TextLabel") then
                hashtag.TextColor3 = selected and UIThemeState.colors.text or UIThemeState.colors.muted
            end
        end
    end
end

-- Discord-style settings palette.  Settings are deliberately themed separately
-- from the feature canvas so changing a feature/theme can never wash the settings
-- screen into one flat color.
UIThemeState.refreshFeatureLabels = function()
    local root = Discord
    if not root then return end
    local c = UIThemeState.colors
    for _, obj in ipairs(root:GetDescendants()) do
        if obj:IsA("TextLabel") then
            local role = obj:GetAttribute("ThemeTextRole")
            if role == "muted" then
                obj.TextColor3 = c.muted
            elseif role == "text" then
                obj.TextColor3 = c.text
            end
        end
    end
end

UIThemeState.refreshSettings = function()
    local root = Discord
    if not root then return end
    local c = UIThemeState.colors
    local function setBg(name, color)
        local obj = root:FindFirstChild(name, true)
        if obj and (obj:IsA("Frame") or obj:IsA("ScrollingFrame") or obj:IsA("TextButton")) then
            obj.BackgroundColor3 = color
        end
    end
    local function setText(name, color)
        local obj = root:FindFirstChild(name, true)
        if obj and obj:IsA("TextLabel") then obj.TextColor3 = color end
    end

    -- Outer Discord settings shell.
    setBg("SettingsFrame", c.bg)
    setBg("Settings", c.panel)
    setBg("LeftFrame", c.bg)

    -- Account card and its inner identity strip.
    setBg("UserPanel", c.card)
    setBg("UserSettingsPad", c.panel)
    setBg("UserPanelUserIcon", c.bg)

    -- Sidebar / header typography.
    setBg("MyAccountBtn", c.active)
    setText("MyAccountBtnTitle", c.text)
    setText("SettingsTitle", c.muted)
    setText("CurrentSettingOpen", c.text)
    setText("DiscordInfo", c.muted)
    setText("UsernameText", c.muted)
    setText("UserSettingsPadUser", c.text)
    setText("UserSettingsPadTag", c.muted)
    setText("UserPanelUser", c.text)
    setText("UserPanelTag", c.muted)
    setText("ChangeAvatarText", c.muted)
    setText("TextLabel", c.muted)

    -- Settings controls.
    setBg("EditBtn", c.accent)
    setBg("CloseSettingsBtn", c.card)
    setBg("CloseSettingsBtnCircle", c.panel)
    local closeIcon = root:FindFirstChild("CloseSettingsBtnIcon", true)
    if closeIcon and closeIcon:IsA("ImageLabel") then closeIcon.ImageColor3 = c.text end
    local settingsIcon = root:FindFirstChild("SettingsOpenBtnIco", true)
    if settingsIcon and settingsIcon:IsA("ImageLabel") then settingsIcon.ImageColor3 = c.muted end

    -- Make the settings cards read as distinct surfaces, while retaining the
    -- rounded Discord-style hierarchy.
    local function ensureStroke(name, color, transparency)
        local obj = root:FindFirstChild(name, true)
        if not obj or not obj:IsA("GuiObject") then return end
        local stroke = obj:FindFirstChild("ThemeStroke")
        if not stroke then
            stroke = Instance.new("UIStroke")
            stroke.Name = "ThemeStroke"
            stroke.Thickness = 1
            stroke.Parent = obj
        end
        stroke.Color = color
        stroke.Transparency = transparency or 0
    end
    ensureStroke("UserPanel", c.divider, 0.25)
    ensureStroke("UserSettingsPad", c.divider, 0.35)
    ensureStroke("MyAccountBtn", c.divider, 0.45)
end

-- =========================================================
-- PERSISTENT FPS CONFIG
-- =========================================================

local FPS_CONFIG_FILE = "botfarm_fps.txt"
local DEFAULT_FPS = 60
local FPS_MIN = 1
local FPS_MAX = 250
local currentFPS = DEFAULT_FPS

local function loadFPS()
    local saved

    pcall(function()
        if isfile and isfile(FPS_CONFIG_FILE) and readfile then
            saved = readfile(FPS_CONFIG_FILE)
        end
    end)

    local value = tonumber(saved)
    if value then
        return math.clamp(math.floor(value), FPS_MIN, FPS_MAX)
    end

    return DEFAULT_FPS
end

local function saveFPS(value)
    local ok = false

    pcall(function()
        if writefile then
            writefile(FPS_CONFIG_FILE, tostring(math.floor(value)))
            ok = true
        end
    end)

    return ok
end

local function applyFPS(value)
    value = math.clamp(math.floor(tonumber(value) or DEFAULT_FPS), FPS_MIN, FPS_MAX)
    currentFPS = value

    pcall(function()
        if type(setfpscap) == "function" then
            setfpscap(value)
        end
    end)
end

currentFPS = loadFPS()
applyFPS(currentFPS)


