local texturesRemoved = false

local function removeAllTextures()
    local removed = 0

    for _, obj in ipairs(game:GetDescendants()) do
        pcall(function()
            if obj:IsA("Decal")
                or obj:IsA("Texture")
                or obj:IsA("SurfaceAppearance") then
                obj:Destroy()
                removed += 1
                return
            end

            if obj:IsA("MeshPart") then
                if obj.TextureID ~= "" then
                    obj.TextureID = ""
                    removed += 1
                end

            elseif obj:IsA("SpecialMesh") then
                if obj.TextureId ~= "" then
                    obj.TextureId = ""
                    removed += 1
                end

            elseif obj:IsA("ParticleEmitter")
                or obj:IsA("Trail")
                or obj:IsA("Beam") then
                if obj.Texture ~= "" then
                    obj.Texture = ""
                    removed += 1
                end
            end
        end)
    end

    texturesRemoved = true

    DiscordLib:Notification(
        "Textures",
        "Removed " .. tostring(removed) .. " texture assets from the current game.",
        "Okay!"
    )
end

