profilesChannel:Label("Profiles")
local function applyPresetProfile(name, announce)
    name = presetProfiles[name] and name or "Custom"
    currentProfileName = name
    saveProfileName(name)
    if profileStatusLabel and profileStatusLabel.Parent then profileStatusLabel.Text = "Current preset: " .. name end
    local preset = presetProfiles[name]
    if not preset then return end
    TARGET_SPEED = math.min(tonumber(preset.speed) or MAX_SAFE_FARM_SPEED, MAX_SAFE_FARM_SPEED)
    applyFPS(preset.fps)
    enabled = preset.autoFarm
    afkActive = preset.antiAfk
    if enabled then
        if not isLoaded then
            loadScript()
        else
            startMovementEngine()
            startTargetFinder()
            startRoleMonitor()
        end
    else
        stopMovement()
        stopNoclip()
    end
    if announce then debugLog("Preset -> " .. name) end
end
profilesChannel:Dropdown("Profile", {"Default", "Safe Farm", "Fast Farm", "Performance", "Custom"}, function(name)
    applyPresetProfile(name, true)
end)
profilesChannel:Label("Auto role profile: Innocent / Sheriff / Murderer")
profileStatusLabel = profilesChannel:Label("Current preset: " .. currentProfileName)
