textbs:Textbox("Discord Webhook", "Paste webhook URL...", false, function(value)
    webhookInput = normalizeWebhook(value)
    if webhookInput == "" then return end
    if not isValidWebhookURL(webhookInput) then
        DiscordLib:Notification("Webhook", "Invalid Discord webhook URL.", "Okay!")
        return
    end
    WEBHOOK_URL = webhookInput
end)
textbs:Button("Save Webhook", function()
    local url = normalizeWebhook(webhookInput)
    if url == "" or not isValidWebhookURL(url) then
        DiscordLib:Notification("Webhook", "Enter a valid Discord webhook URL first.", "Okay!")
        return
    end
    webhookInput, WEBHOOK_URL = url, url
    DiscordLib:Notification("Webhook", saveWebhook(url) and "Webhook saved." or "Webhook set for this session.", "Okay!")
end)
textbs:Button("Test Connection", function()
    task.spawn(function()
        local ok = testWebhook()
        webhookMark(ok, ok and "test delivered" or "test failed")
    end)
end)
textbs:Button("Clear Webhook", function()
    webhookInput, WEBHOOK_URL = "", ""
    pcall(function() if delfile and isfile and isfile(WEBHOOK_CONFIG_FILE) then delfile(WEBHOOK_CONFIG_FILE) end end)
    DiscordLib:Notification("Webhook", "Saved webhook cleared.", "Okay!")
end)
textbs:Toggle("Webhook Updates", webhookEnabled, function(value) webhookEnabled = value end)
textbs:Slider("Update Interval", 15, 300, webhookInterval, function(value)
    webhookInterval = math.clamp(math.floor(tonumber(value) or webhookInterval), 15, 300)
    saveUICustomization()
end)
textbs:Seperator()
textbs:Label("Events")
textbs:Toggle("Send on Round Start", webhookNotifyRoundStart, function(value) webhookNotifyRoundStart = value end)
