        return player:GetAttributeChangedSignal(attributeName):Connect(function()
            updateRoleDisplay(detectRole())
        end)
    end)
    if ok and connection then
        table.insert(roleAttributeConnections, connection)
    end
end


local keyChannel = serv:Channel("⌨ Keybinds")
keyChannel:Label("Click a keybind row and press a new key.")
keyChannel:Bind("Toggle UI", keybinds.ToggleUI, function()
    local controller = previousGlobal.__AH_HUB_UI
    if controller and type(controller.Toggle) == "function" then
        pcall(function() controller.Toggle() end)
    end
end)
keyChannel:Bind("Toggle Auto-Farm", keybinds.AutoFarm, function() enabled = not enabled; if enabled then if not isLoaded then loadScript() else startMovementEngine(); startTargetFinder(); startRoleMonitor() end else stopMovement(); stopNoclip() end end)
