local themesChannel = serv:Channel("🎨 Themes")
themesChannel:Label("Premium appearance • changes are saved automatically")
themesChannel:Dropdown("Theme", {"Midnight", "Crimson", "Purple", "Blue", "Neon", "Minimal", "Premium"}, function(name)
    applyPremiumTheme(name)
    DiscordLib:Notification("Theme", name .. " theme applied.", "Okay!")
end)
themesChannel:Seperator()
themesChannel:Label("UI Customization")
themesChannel:Slider("UI Scale", 75, 125, uiScaleValue, function(value)
    uiScaleValue = value
    if previousGlobal.__AH_HUB_UI then previousGlobal.__AH_HUB_UI.SetScale(compactMode and math.min(uiScaleValue, 92) or uiScaleValue) end
    saveUICustomization()
end)
themesChannel:Slider("Animation Intensity", 25, 150, uiAnimationIntensity, function(value)
    uiAnimationIntensity = value
    saveUICustomization()
end)
local function applyUIBlur(value)
    uiBlurSize = math.clamp(tonumber(value) or 0, 0, 24)
    uiBlurEnabled = uiBlurSize > 0
    if previousGlobal.__AH_HUB_UI and previousGlobal.__AH_HUB_UI.SetBlur then
        previousGlobal.__AH_HUB_UI.SetBlur(uiBlurEnabled, uiBlurSize)
    end
    saveUICustomization()
end

themesChannel:Slider("Blur", 0, 24, uiBlurSize, function(value)
    applyUIBlur(value)
end)
themesChannel:Toggle("Compact Mode", compactMode, function(value)
    compactMode = value
    saveUICustomization()
    if previousGlobal.__AH_HUB_UI then previousGlobal.__AH_HUB_UI.SetScale(value and math.min(uiScaleValue, 92) or uiScaleValue) end
end)

-- Apply after every component has been created.
task.defer(function()
    applyPremiumTheme(activeThemeName)
    if UIThemeState.refreshTabs then UIThemeState.refreshTabs() end
    if UIThemeState.refreshSettings then UIThemeState.refreshSettings() end
    updateRoleDisplay(detectRole())
    if previousGlobal.__AH_HUB_UI then
        previousGlobal.__AH_HUB_UI.SetScale(compactMode and math.min(uiScaleValue, 92) or uiScaleValue)
        previousGlobal.__AH_HUB_UI.SetBlur(uiBlurSize > 0, uiBlurSize)
    end
end)

