lbls:Button("Copy Discord Link", function()
    local inviteUrl = "https://discord.gg/M3yjV8N8rv"
    local webUrl = "https://discord.com/invite/M3yjV8N8rv"
    local appUrl = "discord://-/invite/M3yjV8N8rv"

    -- Copy the invite once per click.
    pcall(function()
        if type(setclipboard) == "function" then
            setclipboard(inviteUrl)
        elseif type(toclipboard) == "function" then
            toclipboard(inviteUrl)
        elseif type(set_clipboard) == "function" then
            set_clipboard(inviteUrl)
        end
    end)

    -- Try each opener once, in order. Stop immediately after one reports success.
    local function try(fn)
        local ok, result = pcall(fn)
        return ok and result == true
    end

    -- 1. Discord app protocol
    if syn and type(syn.open_url) == "function" then
        if try(function()
            syn.open_url(appUrl)
            return true
        end) then return end
    end

    -- 2. Discord web URL through syn
    if syn and type(syn.open_url) == "function" then
        if try(function()
            syn.open_url(webUrl)
            return true
        end) then return end
    end

    -- 3. Generic open_url with Discord app protocol
    if type(open_url) == "function" then
        if try(function()
            open_url(appUrl)
            return true
        end) then return end
    end

    -- 4. Generic open_url with web URL
    if type(open_url) == "function" then
        if try(function()
            open_url(webUrl)
            return true
        end) then return end
    end

    -- 5. openbrowser with Discord app protocol
    if type(openbrowser) == "function" then
        if try(function()
            openbrowser(appUrl)
            return true
        end) then return end
    end

    -- 6. openbrowser with web URL
    if type(openbrowser) == "function" then
        if try(function()
            openbrowser(webUrl)
            return true
        end) then return end
    end

    -- 7. getgenv().open_url with Discord app protocol
    local genv = getgenv and getgenv()
    if genv and type(genv.open_url) == "function" then
        if try(function()
            genv.open_url(appUrl)
            return true
        end) then return end

        -- 8. getgenv().open_url with web URL
        if try(function()
            genv.open_url(webUrl)
            return true
        end) then return end
    end

    -- 9. getgenv().openbrowser with Discord app protocol
    if genv and type(genv.openbrowser) == "function" then
        if try(function()
            genv.openbrowser(appUrl)
            return true
        end) then return end

        -- 10. getgenv().openbrowser with web URL
        if try(function()
            genv.openbrowser(webUrl)
            return true
        end) then return end
    end

    -- 11. Roblox browser API as the final fallback.
    pcall(function()
        local GuiService = game:GetService("GuiService")
        if GuiService and type(GuiService.OpenBrowserWindow) == "function" then
            GuiService:OpenBrowserWindow(webUrl)
        end
    end)
end)

