-- =========================================================
-- GLOBAL ROUNDED UI PASS
-- Keep the premium UI visually consistent by giving every
-- visible GUI control/container a rounded edge. Existing
-- UICorners are preserved so intentional circles and custom
-- radii are not destroyed.
-- =========================================================
local function ensureRoundedGuiObject(guiObject)
    if not guiObject or not guiObject:IsA("GuiObject") then return end
    if guiObject:GetAttribute("AHHubRounded") then return end

    -- Layout/utility GuiObjects do not need a visual corner.
    if guiObject:IsA("UIBase") then return end

    local existing = guiObject:FindFirstChildOfClass("UICorner")
    if existing then
        guiObject:SetAttribute("AHHubRounded", true)
        return
    end

    local corner = Instance.new("UICorner")
    corner.Name = "AHHubRoundedCorner"

    -- Larger containers get a slightly softer radius; small controls
    -- remain compact so the rounding never makes them look pill-shaped.
    local size = guiObject.AbsoluteSize
    local smallest = math.min(size.X > 0 and size.X or 100, size.Y > 0 and size.Y or 32)
    local radius = math.clamp(math.floor(smallest * 0.16 + 0.5), 6, 12)
    corner.CornerRadius = UDim.new(0, radius)
    corner.Parent = guiObject
    guiObject:SetAttribute("AHHubRounded", true)
end

local function applyRoundedUiTree(root)
    if not root then return end
    if root:IsA("GuiObject") then
        ensureRoundedGuiObject(root)
    end
    for _, descendant in ipairs(root:GetDescendants()) do
        if descendant:IsA("GuiObject") then
            ensureRoundedGuiObject(descendant)
        end
    end
end

-- Apply once to everything already built, then automatically cover
-- controls created later by channels, menus, notifications, etc.
task.defer(function()
    if Discord and Discord.Parent then
        applyRoundedUiTree(Discord)
        Discord.DescendantAdded:Connect(function(descendant)
            if descendant:IsA("GuiObject") then
                task.defer(function()
                    if descendant and descendant.Parent then
                        ensureRoundedGuiObject(descendant)
                    end
                end)
            end
        end)
    end
end)

